/**
 * shadcn's `sidebar-06`, ported from
 * `apps/v4/registry/new-york-v4/blocks/sidebar-06/`.
 */

import { For, Show, type Incoming } from "@barqjs/core";
import { css } from "@barqjs/css";
import {
  Breadcrumb,
  BreadcrumbItem,
  BreadcrumbLink,
  BreadcrumbList,
  BreadcrumbPage,
  BreadcrumbSeparator,
} from "../ui/breadcrumb.tsx";
import { Button } from "../ui/button.tsx";
import { Card, CardContent, CardDescription, CardHeader, CardTitle } from "../ui/card.tsx";
import {
  DropdownMenu,
  DropdownMenuContent,
  DropdownMenuItem,
  DropdownMenuTrigger,
} from "../ui/dropdown-menu.tsx";
import { Separator } from "../ui/separator.tsx";
import {
  Sidebar,
  SidebarContent,
  SidebarFooter,
  SidebarGroup,
  SidebarHeader,
  SidebarInput,
  SidebarInset,
  SidebarMenu,
  SidebarMenuButton,
  SidebarMenuItem,
  SidebarProvider,
  SidebarRail,
  SidebarTrigger,
  useSidebar,
} from "../ui/sidebar.tsx";
import { Ellipsis } from "@barqjs/lucide/icons/ellipsis";
import { GalleryVerticalEnd } from "@barqjs/lucide/icons/gallery-vertical-end";
import { blockFillsPreview } from "../lib/layout.ts";

const header = css`
  display: flex;
  height: 4rem;
  flex-shrink: 0;
  align-items: center;
  gap: 0.5rem;
  border-bottom: 1px solid var(--border);
  padding-inline: 1rem;
`;

const trigger = css`
  margin-left: -0.25rem;
`;

const rule = css`
  margin-right: 0.5rem;
  height: 1rem;
`;

const wideOnly = css`
  display: none;

  @media (width >= 48rem) {
    display: block;
  }
`;

const body = css`
  display: flex;
  flex: 1;
  flex-direction: column;
  gap: 1rem;
  padding: 1rem;
`;

const tiles = css`
  display: grid;
  grid-auto-rows: min-content;
  gap: 1rem;

  @media (width >= 48rem) {
    grid-template-columns: repeat(3, minmax(0, 1fr));
  }
`;

const tile = css`
  aspect-ratio: 16 / 9;
  border-radius: var(--radius-xl, calc(var(--radius) + 4px));
  background: color-mix(in oklab, var(--muted) 50%, transparent);
`;

const panel = css`
  min-height: 100vh;
  flex: 1;
  border-radius: var(--radius-xl, calc(var(--radius) + 4px));
  background: color-mix(in oklab, var(--muted) 50%, transparent);

  @media (width >= 48rem) {
    min-height: min-content;
  }
`;

const mark = css`
  display: flex;
  aspect-ratio: 1 / 1;
  width: 2rem;
  height: 2rem;
  align-items: center;
  justify-content: center;
  border-radius: var(--radius);
  background: var(--sidebar-primary);
  color: var(--sidebar-primary-foreground);

  & svg {
    width: 1rem;
    height: 1rem;
  }
`;

const stack = css`
  display: flex;
  flex-direction: column;
  gap: 0.125rem;
  line-height: 1;
`;

const medium = css`
  font-weight: 500;
`;

const openLook = css`
  &[aria-expanded="true"] {
    background: var(--sidebar-accent);
    color: var(--sidebar-accent-foreground);
  }
`;

const trailing = css`
  margin-left: auto;
`;

const flyout = css`
  width: auto;
  min-width: 14rem;
  border-radius: var(--radius);
`;

const footerPad = css`
  padding: 0.25rem;
`;

const optIn = css`
  gap: 0.5rem;
  padding-block: 1rem;
  box-shadow: none;
`;

const optInPad = css`
  padding-inline: 1rem;
`;

const optInTitle = css`
  font-size: 0.875rem;
`;

const optInFields = css`
  display: grid;
  gap: 0.625rem;
`;

const subscribe = css`
  width: 100%;
  background: var(--sidebar-primary);
  color: var(--sidebar-primary-foreground);
  box-shadow: none;
`;

interface NavLink {
  readonly title: string;
  readonly url: string;
  readonly isActive?: boolean;
}

interface NavSection {
  readonly title: string;
  readonly url: string;
  readonly items: readonly NavLink[];
}

const NAV_MAIN: readonly NavSection[] = [
  {
    title: "Getting Started",
    url: "#",
    items: [
      { title: "Installation", url: "#" },
      { title: "Project Structure", url: "#" },
    ],
  },
  {
    title: "Build Your Application",
    url: "#",
    items: [
      { title: "Routing", url: "#" },
      { title: "Data Fetching", url: "#", isActive: true },
      { title: "Rendering", url: "#" },
      { title: "Caching", url: "#" },
      { title: "Styling", url: "#" },
      { title: "Optimizing", url: "#" },
      { title: "Configuring", url: "#" },
      { title: "Testing", url: "#" },
      { title: "Authentication", url: "#" },
      { title: "Deploying", url: "#" },
      { title: "Upgrading", url: "#" },
      { title: "Examples", url: "#" },
    ],
  },
  {
    title: "API Reference",
    url: "#",
    items: [
      { title: "Components", url: "#" },
      { title: "File Conventions", url: "#" },
      { title: "Functions", url: "#" },
      { title: "next.config.js Options", url: "#" },
      { title: "CLI", url: "#" },
      { title: "Edge Runtime", url: "#" },
    ],
  },
  {
    title: "Architecture",
    url: "#",
    items: [
      { title: "Accessibility", url: "#" },
      { title: "Fast Refresh", url: "#" },
      { title: "Next.js Compiler", url: "#" },
      { title: "Supported Browsers", url: "#" },
      { title: "Turbopack", url: "#" },
    ],
  },
];

function NavMain(props: Incoming<{ items: readonly NavSection[] }>) {
  const sidebar = useSidebar();

  return (
    <SidebarGroup>
      <SidebarMenu>
        <For each={() => props.items()}>
          {(section: NavSection) => (
            <DropdownMenu>
              <SidebarMenuItem>
                <DropdownMenuTrigger>
                  <SidebarMenuButton class={openLook}>
                    {section.title} <Ellipsis class={trailing} />
                  </SidebarMenuButton>
                </DropdownMenuTrigger>
                <Show when={section.items.length > 0}>
                  <DropdownMenuContent
                    side={sidebar.isMobile() ? "bottom" : "right"}
                    align={sidebar.isMobile() ? "end" : "start"}
                    class={flyout}
                  >
                    <For each={() => section.items}>
                      {(item: NavLink) => (
                        <DropdownMenuItem href={item.url}>{item.title}</DropdownMenuItem>
                      )}
                    </For>
                  </DropdownMenuContent>
                </Show>
              </SidebarMenuItem>
            </DropdownMenu>
          )}
        </For>
      </SidebarMenu>
    </SidebarGroup>
  );
}

function SidebarOptInForm() {
  return (
    <Card class={optIn}>
      <CardHeader class={optInPad}>
        <CardTitle class={optInTitle}>Subscribe to our newsletter</CardTitle>
        <CardDescription>Opt-in to receive updates and news about the sidebar.</CardDescription>
      </CardHeader>
      <CardContent class={optInPad}>
        <form>
          <div class={optInFields}>
            <SidebarInput type="email" placeholder="Email" aria-label="Email" />
            <Button type="submit" size="sm" class={subscribe}>
              Subscribe
            </Button>
          </div>
        </form>
      </CardContent>
    </Card>
  );
}

function AppSidebar() {
  return (
    <Sidebar>
      <SidebarHeader>
        <SidebarMenu>
          <SidebarMenuItem>
            <SidebarMenuButton size="lg" href="#">
              <div class={mark}>
                <GalleryVerticalEnd />
              </div>
              <div class={stack}>
                <span class={medium}>Documentation</span>
                <span>v1.0.0</span>
              </div>
            </SidebarMenuButton>
          </SidebarMenuItem>
        </SidebarMenu>
      </SidebarHeader>
      <SidebarContent>
        <NavMain items={NAV_MAIN} />
      </SidebarContent>
      <SidebarFooter>
        <div class={footerPad}>
          <SidebarOptInForm />
        </div>
      </SidebarFooter>
      <SidebarRail />
    </Sidebar>
  );
}

export function Sidebar06() {
  return (
    <SidebarProvider class={blockFillsPreview}>
      <AppSidebar />
      <SidebarInset>
        <header class={header}>
          <SidebarTrigger class={trigger} />
          <Separator orientation="vertical" class={rule} />
          <Breadcrumb>
            <BreadcrumbList>
              <BreadcrumbItem class={wideOnly}>
                <BreadcrumbLink href="#">Build Your Application</BreadcrumbLink>
              </BreadcrumbItem>
              <BreadcrumbSeparator class={wideOnly} />
              <BreadcrumbItem>
                <BreadcrumbPage>Data Fetching</BreadcrumbPage>
              </BreadcrumbItem>
            </BreadcrumbList>
          </Breadcrumb>
        </header>
        <div class={body}>
          <div class={tiles}>
            <div class={tile} />
            <div class={tile} />
            <div class={tile} />
          </div>
          <div class={panel} />
        </div>
      </SidebarInset>
    </SidebarProvider>
  );
}
